import {createThreeRingConfig,resetThreeRing,rotateThreeRing,evaluateThreeRing,RING_IDS} from './three-ring-reliquary-engine.js';
const el=app=>app.element?.[0]??app.element;
function markup(config,state,message=''){const check=evaluateThreeRing(config,state);const rings=RING_IDS.map((id,i)=>`<div class="rw-reliquary-ring"><strong>${id.toUpperCase()}</strong><div class="rw-reliquary-symbol">${check.display[i]}</div><button type="button" data-ring="${id}" data-direction="-1" aria-label="Rotate ${id} ring counterclockwise">◀</button><button type="button" data-ring="${id}" data-direction="1" aria-label="Rotate ${id} ring clockwise">▶</button></div>`).join('');return `<section class="rw-reliquary"><h2>Rosewater Reliquary</h2><p>Rotate the three symbol rings to align the seal.</p><div class="rw-reliquary-rings">${rings}</div><button type="button" data-reliquary-submit>Press central seal</button><button type="button" data-reliquary-reset>Reset test</button><p role="status">${message||'Three rings await alignment.'}</p></section>`;}
export async function openStandaloneThreeRingReliquaryPuzzle(){const DialogV2=globalThis.foundry?.applications?.api?.DialogV2;if(!DialogV2)throw Error('Foundry DialogV2 missing');const config=createThreeRingConfig({solution:[1,3,5]});class Dialog extends DialogV2{constructor(){const state=resetThreeRing(config);super({classes:['regionwright','rw-reliquary-dialog'],window:{title:'Rosewater Reliquary — test',resizable:true},position:{width:580,height:440},content:markup(config,state),buttons:[{action:'close',label:'Close'}]});this.state=state;} _onRender(context,options){super._onRender(context,options);el(this)?.addEventListener('click',e=>{const ring=e.target.closest?.('[data-ring]');if(ring){this.state=rotateThreeRing(config,this.state,ring.dataset.ring,Number(ring.dataset.direction));this.refresh();return;}if(e.target.closest?.('[data-reliquary-reset]')){this.state=resetThreeRing(config);this.refresh('The rings return to their starting marks.');return;}if(e.target.closest?.('[data-reliquary-submit]'))this.refresh(evaluateThreeRing(config,this.state).success?'The Reliquary seal releases.':'The symbol sequence does not align.');});}refresh(message=''){const node=el(this)?.querySelector('.rw-reliquary');if(node)node.outerHTML=markup(config,this.state,message);}}const dialog=new Dialog();await dialog.render({force:true});return dialog;}
